from uuid import UUID

from fastapi import HTTPException, status
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session, selectinload

from ..models import AgentDispatch, DispatchStatus, Source, WorkEvidence, WorkItem, WorkStatus
from ..schemas import (AgentDispatchRequest, AgentDispatchUpdate, EvidenceInput, SourceCreate, SourceUpdate,
                       WorkItemCreate, WorkItemUpdate)


def not_found(entity: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"{entity} not found")


def conflict(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_409_CONFLICT, detail=detail)


def get_work_item(db: Session, item_id: UUID) -> WorkItem:
    item = db.scalar(select(WorkItem).options(selectinload(WorkItem.evidence)).where(WorkItem.id == item_id))
    if item is None:
        raise not_found("Work item")
    return item


def list_work_items(db: Session, status_filter: WorkStatus | None, source_kind: str | None, assigned_agent: str | None) -> list[WorkItem]:
    query = select(WorkItem).options(selectinload(WorkItem.evidence)).order_by(WorkItem.updated_at.desc())
    if status_filter:
        query = query.where(WorkItem.status == status_filter)
    if source_kind:
        query = query.where(WorkItem.source_kind == source_kind)
    if assigned_agent:
        query = query.where(WorkItem.assigned_agent == assigned_agent)
    return list(db.scalars(query))


def create_work_item(db: Session, payload: WorkItemCreate) -> WorkItem:
    data = payload.model_dump(exclude={"evidence"}, mode="json")
    data["source_url"] = str(data["source_url"]) if data.get("source_url") else None
    item = WorkItem(**data)
    for evidence in payload.evidence:
        item.evidence.append(WorkEvidence(**evidence.model_dump(exclude={"observed_at"}), observed_at=evidence.observed_at))
    db.add(item)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise conflict("A work item with this source_external_id already exists")
    return get_work_item(db, item.id)


def update_work_item(db: Session, item_id: UUID, payload: WorkItemUpdate) -> WorkItem:
    item = get_work_item(db, item_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(item, key, value)
    db.commit()
    return get_work_item(db, item.id)


def delete_work_item(db: Session, item_id: UUID) -> None:
    db.delete(get_work_item(db, item_id))
    db.commit()


def add_evidence(db: Session, item_id: UUID, payload: EvidenceInput) -> WorkEvidence:
    item = get_work_item(db, item_id)
    evidence = WorkEvidence(
        work_item_id=item.id,
        **payload.model_dump(exclude={"observed_at"}),
        observed_at=payload.observed_at,
    )
    db.add(evidence)
    db.commit()
    db.refresh(evidence)
    return evidence


def delete_evidence(db: Session, item_id: UUID, evidence_id: UUID) -> None:
    get_work_item(db, item_id)
    evidence = db.get(WorkEvidence, evidence_id)
    if evidence is None or evidence.work_item_id != item_id:
        raise not_found("Evidence")
    db.delete(evidence)
    db.commit()


def get_source(db: Session, source_id: UUID) -> Source:
    source = db.get(Source, source_id)
    if source is None:
        raise not_found("Source")
    return source


def create_source(db: Session, payload: SourceCreate) -> Source:
    data = payload.model_dump(mode="json")
    data["url"] = str(data["url"]) if data.get("url") else None
    source = Source(**data)
    db.add(source)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise conflict("A source with this external_id already exists")
    return get_source(db, source.id)


def update_source(db: Session, source_id: UUID, payload: SourceUpdate) -> Source:
    source = get_source(db, source_id)
    data = payload.model_dump(exclude_unset=True, mode="json")
    if "url" in data:
        data["url"] = str(data["url"]) if data["url"] else None
    for key, value in data.items():
        setattr(source, key, value)
    db.commit()
    return get_source(db, source_id)


def delete_source(db: Session, source_id: UUID) -> None:
    db.delete(get_source(db, source_id))
    db.commit()


def create_dispatch(db: Session, payload: AgentDispatchRequest) -> AgentDispatch:
    get_work_item(db, payload.work_item_id)
    dispatch = AgentDispatch(**payload.model_dump())
    db.add(dispatch)
    db.commit()
    db.refresh(dispatch)
    return dispatch


def update_dispatch(db: Session, dispatch_id: UUID, payload: AgentDispatchUpdate) -> AgentDispatch:
    dispatch = db.get(AgentDispatch, dispatch_id)
    if dispatch is None:
        raise not_found("Agent dispatch")
    dispatch.status = payload.status
    if payload.result is not None:
        dispatch.result = payload.result
    db.commit()
    db.refresh(dispatch)
    return dispatch


def list_dispatches(db: Session, work_item_id: UUID | None = None) -> list[AgentDispatch]:
    query = select(AgentDispatch).order_by(AgentDispatch.created_at.desc())
    if work_item_id:
        query = query.where(AgentDispatch.work_item_id == work_item_id)
    return list(db.scalars(query))

"""Read-only sync orchestration and deliberately minimal local sync status."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any
from sqlalchemy.orm import Session

from ..config import Settings
from ..integrations.graph import GraphClient
from .crypto import EncryptedTokenStore, TokenStoreError
from .graph import fetch_signals, persist_signals
from .sync_registry import UnknownSourceKindError, get_sync_handler, register_sync_handler

GRAPH_SOURCE_KIND = "graph"


class SyncError(RuntimeError):
    pass


def token_store(settings: Settings) -> EncryptedTokenStore:
    key = settings.app_encryption_key
    if key is None:
        raise SyncError("APP_ENCRYPTION_KEY is not configured")
    return EncryptedTokenStore(settings.token_store_path, key.get_secret_value())


def status(settings: Settings) -> dict[str, Any]:
    configured = not settings.graph_configuration_errors()
    try:
        connected = token_store(settings).load() is not None
    except (SyncError, TokenStoreError):
        connected = False
    return {"configured": configured, "connected": connected, "mode": "read-only", "last_sync_at": None}


def _sync_graph(settings: Settings, db: Session | None = None, limit: int = 50, client: GraphClient | None = None, **_: Any) -> dict[str, Any]:
    """The only handler that knows about Microsoft Graph; the identity assertion
    below is Graph-specific and must not apply to any other registered kind."""
    if settings.graph_configuration_errors():
        raise SyncError("Microsoft Graph is not configured")
    try:
        token = token_store(settings).load()
    except TokenStoreError as error:
        raise SyncError("Stored Graph credentials are unavailable") from error
    if not token or not isinstance(token.get("access_token"), str):
        raise SyncError("Microsoft Graph is not connected")
    graph = client or GraphClient(token["access_token"])
    profile = graph.me()
    if profile.get("id") != settings.microsoft_target_user_id:
        raise SyncError("connected Microsoft user does not match MICROSOFT_TARGET_USER_ID")
    signals = fetch_signals(graph, limit)
    created = persist_signals(db, signals) if db is not None else 0
    return {"mode": "read-only", "synced_at": datetime.now(UTC).isoformat(), "count": len(signals), "new_sources": created}


register_sync_handler(GRAPH_SOURCE_KIND, _sync_graph)


def sync(settings: Settings, db: Session | None = None, client: GraphClient | None = None, limit: int = 50, kind: str = GRAPH_SOURCE_KIND) -> dict[str, Any]:
    """Dispatch to whatever handler is registered for ``kind``.

    Adding a new source kind (Jira, Freshservice, ...) means registering a
    handler for it elsewhere -- nothing here has to change.
    """
    try:
        handler = get_sync_handler(kind)
    except UnknownSourceKindError as error:
        raise SyncError(str(error)) from error
    return handler(settings, db=db, limit=limit, client=client)
=====REGISTRY=====
"""Registry of sync handlers, keyed by source kind.

``sync()`` in :mod:`app.services.sync` used to be hardwired to Microsoft Graph.
Adding a second connector (Jira, Freshservice, ...) meant editing its body. This
registry lets a connector register a handler for its own kind instead -- so a new
kind shows up by calling :func:`register_sync_handler` once, from wherever that
connector lives, without touching ``sync()``.
"""

from __future__ import annotations

from typing import Any, Callable

# A handler receives the same shape ``sync()`` always did (settings, an optional
# db session, and a limit) plus any connector-specific extras as keyword-only
# args (e.g. Graph's ``client``), and returns the same result envelope ``sync()``
# has always returned.
SyncHandler = Callable[..., dict[str, Any]]

_handlers: dict[str, SyncHandler] = {}


class UnknownSourceKindError(RuntimeError):
    """Raised when nothing is registered for the requested source kind."""


def register_sync_handler(kind: str, handler: SyncHandler) -> None:
    _handlers[kind] = handler


def unregister_sync_handler(kind: str) -> None:
    _handlers.pop(kind, None)


def get_sync_handler(kind: str) -> SyncHandler:
    try:
        return _handlers[kind]
    except KeyError as error:
        raise UnknownSourceKindError(f"no sync handler registered for source kind {kind!r}") from error


def registered_kinds() -> tuple[str, ...]:
    return tuple(_handlers)
=====FIELDCRYPTO=====
"""Column-level AES-GCM encryption for message content kept in the local database.

The primitive is the same one ``crypto.EncryptedTokenStore`` uses, under the same
``APP_ENCRYPTION_KEY``, but sealed with its own associated data: a ciphertext
written for a database column must never verify as a stored Graph token, and vice
versa. There is no second key and no fallback -- a value that cannot be sealed or
opened raises, so cleartext can never reach the disk and garbage can never reach
the API.
"""

from __future__ import annotations

import base64
import binascii
import os

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from sqlalchemy import Text
from sqlalchemy.types import TypeDecorator

from ..config import get_settings

# Deliberately not ``b"workboard-graph-v1"``; that string belongs to the token store.
EXCERPT_AAD = b"workboard-source-excerpt-v1"

# Tags the stored form so a migration can tell a sealed column from a legacy one.
CIPHERTEXT_PREFIX = "aesgcm.v1:"

NONCE_BYTES = 12


class FieldEncryptionError(RuntimeError):
    pass


def _cipher() -> AESGCM:
    key = get_settings().app_encryption_key
    if key is None:
        raise FieldEncryptionError("APP_ENCRYPTION_KEY is not configured; message content cannot be stored")
    try:
        return AESGCM(base64.urlsafe_b64decode(key.get_secret_value().encode()))
    except (ValueError, TypeError, binascii.Error) as error:
        raise FieldEncryptionError("APP_ENCRYPTION_KEY must be a 32-byte URL-safe base64 key") from error


def encrypt_text(value: str) -> str:
    nonce = os.urandom(NONCE_BYTES)
    sealed = nonce + _cipher().encrypt(nonce, value.encode(), EXCERPT_AAD)
    return CIPHERTEXT_PREFIX + base64.urlsafe_b64encode(sealed).decode()


def decrypt_text(stored: str) -> str:
    if not stored.startswith(CIPHERTEXT_PREFIX):
        raise FieldEncryptionError("stored message content is not encrypted; run the Alembic migrations")
    try:
        raw = base64.urlsafe_b64decode(stored[len(CIPHERTEXT_PREFIX):].encode())
        return _cipher().decrypt(raw[:NONCE_BYTES], raw[NONCE_BYTES:], EXCERPT_AAD).decode()
    except (InvalidTag, ValueError, TypeError, binascii.Error, UnicodeDecodeError) as error:
        raise FieldEncryptionError("stored message content cannot be decrypted") from error


class EncryptedText(TypeDecorator[str]):
    """A ``TEXT`` column whose value is sealed on write and opened on read.

    Encrypting in the type rather than at the call sites means every writer of the
    column -- Graph sync, the REST API, a future integration -- is covered by
    construction, and every reader keeps seeing cleartext.
    """

    impl = Text
    cache_ok = True

    def process_bind_param(self, value: str | None, _dialect: object) -> str | None:
        return None if value is None else encrypt_text(value)

    def process_result_value(self, value: str | None, _dialect: object) -> str | None:
        return None if value is None else decrypt_text(value)

from functools import lru_cache

from pathlib import Path
from urllib.parse import urlparse

from pydantic import SecretStr, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    """Application configuration loaded from environment variables."""

    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    app_env: str = "development"
    log_level: str = "INFO"
    database_url: str = "sqlite:////data/workboard.db"
    microsoft_tenant_id: str | None = None
    microsoft_client_id: str | None = None
    microsoft_client_secret: SecretStr | None = None
    microsoft_target_user_id: str | None = None
    microsoft_redirect_uri: str = "http://localhost:8787/api/auth/callback"
    app_encryption_key: SecretStr | None = None
    # Distinct from Graph/OAuth secrets. Installed local agents use this only
    # as ``Authorization: Bearer ...`` when accessing the agent protocol.
    local_api_token: SecretStr | None = None
    local_session_ttl_seconds: int = 28_800
    max_request_body_bytes: int = 1_048_576
    token_store_path: Path = Path("/data/workboard-graph-tokens.json")
    oauth_state_store_path: Path = Path("/data/workboard-oauth-state.json")

    @field_validator("microsoft_redirect_uri")
    @classmethod
    def redirect_uri_is_safe(cls, value: str) -> str:
        """Only allow a local development callback over HTTP."""
        parsed = urlparse(value)
        if parsed.path != "/api/auth/callback":
            raise ValueError("MICROSOFT_REDIRECT_URI must end in /api/auth/callback")
        if parsed.scheme == "https" or (parsed.scheme == "http" and parsed.hostname in {"localhost", "127.0.0.1"}):
            return value
        raise ValueError("MICROSOFT_REDIRECT_URI must use HTTPS or localhost HTTP")

    @field_validator("microsoft_tenant_id", "microsoft_client_id", "microsoft_target_user_id")
    @classmethod
    def graph_identifiers_are_not_urls(cls, value: str | None) -> str | None:
        if value is not None and (not value.strip() or any(char in value for char in "/\\?&#")):
            raise ValueError("Microsoft identifiers must be plain tenant, client, or object IDs")
        return value

    def graph_configuration_errors(self) -> list[str]:
        required = {
            "MICROSOFT_TENANT_ID": self.microsoft_tenant_id,
            "MICROSOFT_CLIENT_ID": self.microsoft_client_id,
            "MICROSOFT_CLIENT_SECRET": self.microsoft_client_secret,
            "MICROSOFT_TARGET_USER_ID": self.microsoft_target_user_id,
            "APP_ENCRYPTION_KEY": self.app_encryption_key,
        }
        def present(value: str | SecretStr | None) -> bool:
            if isinstance(value, SecretStr):
                return bool(value.get_secret_value().strip())
            return bool(value and value.strip())
        return [name for name, value in required.items() if not present(value)]


@lru_cache
def get_settings() -> Settings:
    return Settings()
