from ..integrations.graph import GraphClient
from ..models import Source, SourceKind

# How much message body a normalized signal carries, for every consumer of one.
EXCERPT_LIMIT = 2_000


def _address(entry: Any) -> str:
    """The lowercased SMTP address inside a Graph ``emailAddress`` wrapper."""
    wrapper = entry.get("emailAddress") if isinstance(entry, dict) else None
    address = wrapper.get("address") if isinstance(wrapper, dict) else None
    return str(address or "").strip().lower()


def normalize_email(row: dict[str, Any]) -> dict[str, Any]:
    # ``sender``, ``recipients`` and ``headers`` are addressing metadata, not body:
    # nothing persists them, they exist so the promotion heuristic can tell a
    # colleague's request from a mailing list.
    headers = row.get("internetMessageHeaders") or []
    return {
        "external_id": f"outlook:{row['id']}", "source_kind": "outlook_email",
        "title": row.get("subject") or "(no subject)",
        "excerpt": (row.get("bodyPreview") or "")[:EXCERPT_LIMIT],
        "source_url": row.get("webLink"), "observed_at": row.get("receivedDateTime"),
        "sender": _address(row.get("from")),
        "recipients": [address for address in map(_address, row.get("toRecipients") or []) if address],
        "headers": {str(header.get("name") or "").strip().lower(): str(header.get("value") or "")
                    for header in headers if isinstance(header, dict)},
    }


def normalize_teams(row: dict[str, Any]) -> dict[str, Any]:
    body = row.get("body") or {}
    content = body.get("content") if isinstance(body, dict) else str(body)
    return {"external_id": f"teams:{row['id']}", "source_kind": "teams_message", "title": row.get("chatTopic") or "Teams conversation", "excerpt": (content or "")[:EXCERPT_LIMIT], "source_url": row.get("webUrl"), "observed_at": row.get("createdDateTime")}


def parse_observed_at(value: Any) -> datetime:
    """Graph's ISO-8601 timestamp, falling back to now when absent or unreadable."""
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")) if value else datetime.now()
    except ValueError:
        return datetime.now()

